/* ---------- 六、彈藥配比的效果 ---------- */
/* 一組彈藥（[[鍵, 發數], ...]）對某門砲的平均效果：對人、對裝甲、穿甲（平均與最好的一種各半）、聚能比例、精度、射程、每發價格 */
/* 動能彈的穿甲隨砲管倍徑變化（膛口初速約與倍徑的 0.2 次方成正比，穿深約與初速的 2 次方成正比 → 穿深約與倍徑的 0.4 次方成正比，換成等級約 1.02 × ln 比值）；成形裝藥不受影響 */
function amPen(a,L){var p=a.pen;if(p>0&&!a.ce&&L>0&&a.refL>0&&L!==a.refL)p+=1.02*Math.log(L/a.refL);return p;}
function amEff(A,w,Lb){var o={n:0,P:0,A:0,pen:0,ce:0,acc:0,rng:0,usd:0,atn:0},pw=0,cw=0,L=+Lb||w&&w.L||0;
  (A||[]).forEach(function(x){var a=GAM[x[0]],r=+x[1]||0;if(!a||!(r>0))return;o.n+=r;o.P+=r*a.p;o.A+=r*a.a;o.acc+=r*a.acc;o.rng+=r*a.rng;o.usd+=r*a.usd;if(a.pen>0){o.atn+=r;pw+=r*amPen(a,L);if(a.ce)cw+=r;}});
  if(!o.n)return o;['P','A','acc','rng','usd'].forEach(function(k){o[k]/=o.n;});
  if(o.atn){var avg=pw/o.atn,best=avg;(A||[]).forEach(function(x){var a=GAM[x[0]],r=+x[1]||0;if(a&&a.pen>0&&r>=0.05*o.atn)best=Math.max(best,amPen(a,L));});o.pen=0.5*avg+0.5*best;o.ce=cw/o.atn;}
  return o;}
/* 榴彈的破片殺傷半徑（公尺，約略）：機砲彈約口徑的 0.15 倍，砲彈約 0.33 倍 */
function amFrag(a,w){var c=w&&w.cal||0;if(!c||a.pen>0&&a.kind!=='heat')return 0;return Math.round(c<40?c*0.15:c*0.33);}
function amFor(wk){var o=[];for(var k in GAM)if(GAM[k].w.indexOf(wk)>=0)o.push(GAM[k]);return o.sort(function(a,b){return a.y-b.y||(a.n<b.n?-1:1);});}
function amClean(A,wk){if(!Array.isArray(A))return null;var o=[];A.forEach(function(x){if(!Array.isArray(x))return;var a=GAM[x[0]],n=Math.round(+x[1]||0);if(a&&a.w.indexOf(wk)>=0&&n>0&&n<=2000&&!o.some(function(q){return q[0]===x[0];}))o.push([x[0],n]);});return o.length?o.slice(0,12):null;}
/* 每種彈藥標示的穿甲是用第一種適用武器的砲管倍徑量的 */
Object.keys(GAM).forEach(function(k){var a=GAM[k],w=WPNO[a.w[0]];a.refL=w&&w.L||0;});
/* 具體武器的穿甲等級、聚能比例、每基數發數與每發價格依原廠配比換算 */
Object.keys(WPNO).forEach(function(k){var w=WPNO[k];if(!w.am0)return;var E=amEff(w.am0,w);if(E.atn){w.pen=Math.round(E.pen*10)/10;w.ce=Math.round(E.ce*100)/100;}if(E.n)w.rpu=Math.round(E.n);if(E.usd)w.rusd=Math.round(E.usd);});

