  if(br==='arm')A(y<1925?'tgun1':y<1955?(K==='ht1940'?'tgunh':'tgun'):mbt,1);
  else if(br==='at'){if(t.mob==='track')A('tgun',1);else if(y>=1960&&t.mob!=='foot')A(atgm,1);}
  else if(br==='mech'){if(y>=1960){A('acan',1);if(y>=1975)A(atgm,0.5);}}
  else if(br==='rec'){if(t.mob!=='horse'&&y>=1960)A(atgm,1/3);}
