function vmArmAdd(m,V){var o={arm:0,armC:0,vrm:1,usd:0};vmAdList(m,V).forEach(function(a){o.arm+=a.arm;o.armC+=a.armC;o.vrm*=a.vrm;o.usd+=a.usd;});return o;}
/* 主武器用的彈藥：單位自訂 → 本方列裝 → 型號原廠 → 武器預設 */
function vmAmmo(u,m){var V=u.vm||{},g=m.m&&m.m[0],w=g&&wpnOf(g);if(!w||!w.am0)return null;var F=fldOf(u.side);
  return Array.isArray(V.am)&&V.am.length?V.am:F&&F.a&&Array.isArray(F.a[g])&&F.a[g].length?F.a[g]:m.am||w.am0;}
