function vmClean(V){if(!V||typeof V!=='object')return null;if(V.m==='-')return {m:'-'};var m=vmOf(V.m);if(!m)return null;var o={m:m.k};if(V.src==='f')o.src='f';
  if(Array.isArray(V.ad))o.ad=V.ad.filter(function(k,i,A){return typeof k==='string'&&VAD[k]&&A.indexOf(k)===i;}).slice(0,12);var g=m.m&&m.m[0],gw=g&&wpnOf(g);if(V.am&&g){var A=amClean(V.am,g);if(A)o.am=A;}if(V.L&&gw&&gw.Lo&&gw.Lo.indexOf(+V.L)>=0&&+V.L!==gw.L)o.L=+V.L;return o;}

/* ---------- 八、列裝表（一方的制式裝備）：v 各角色的制式載具、w 泛用武器 → 具體武器、a 各門砲的制式彈藥配比、e 支援裝備的配發比例 ---------- */
function fldOf(side){var S=G&&G.sides&&G.sides[side];return S&&S.fld||null;}
