/* 支援裝備發給哪些單位：人員裝備給地面部隊，車輛裝備給有裝甲車輛的單位，單位裝備每個單位一件 */
function fldEqFits(e,u){var s=ST(u);if(s.dom!=='land')return false;if(e.cov==='m')return (u.men0||0)>0;if(e.cov==='v')return (u.veh0||0)>0&&s.hard>=0.3;return true;}
var FTC={};
/* 設定列裝表：開戰前立即換裝；作戰中新的部隊與增援直接使用，現有部隊在後方休整時換裝 */
function fldSet(side,F){var S=G.sides[side];if(!S)return 0;var old=S.fld,o=fldClean(F);if(o&&!fldEmpty(o)){o.ver=((old&&old.ver)||0)+1;S.fld=o;}else if(old){S.fld={v:{},w:{},a:{},e:{},ver:(old.ver||0)+1};}FTC={};return fldApply(side);}
function fldApply(side){var n=0;G.units.forEach(function(u){if(u.side!==side||!u.lg)return;if(G.started&&alive(u)&&!(u.refit&&u.st==='off')){u.vmPend=1;return;}if(eqSync(u))n++;});return n;}

/* ---------- 九、換裝：型號的武器與裝備、列裝表的武器與支援裝備；全部記帳，換回時能還原 ---------- */
function wAdd(A,k,n){if(!A||!k||!n)return;for(var i=0;i<A.length;i++)if(A[i][0]===k){A[i][1]=Math.round((A[i][1]+n)*1000)/1000;if(A[i][1]<=0.0005)A.splice(i,1);return;}if(n>0)A.push([k,Math.round(n*1000)/1000]);}
function wHave(A,k){for(var i=0;i<(A||[]).length;i++)if(A[i][0]===k)return A[i][1];return 0;}
/* 拿走 n 件：整筆拿光時記下原本的位置，還原時放回同一個位置 */
function wTake(A,k,n){var i=-1;for(var j=0;j<A.length;j++)if(A[j][0]===k){i=j;break;}if(i<0)return null;var d=Math.min(n,A[i][1]);if(!(d>0))return null;A[i][1]=Math.round((A[i][1]-d)*1000)/1000;var at=-1;if(A[i][1]<=0.0005){A.splice(i,1);at=i;}return [k,d,at];}
