  if(L.length){var s=0;L.forEach(function(p){s+=rpPresetCost(p.k);});r={v:Math.round(s/L.length),src:L.map(function(p){return p.n;}),est:0};}
  else{var t=fpStdCo(era,kind);if(t){var v=fpType(t.k)*FPEM[ech];if(ech>=2)v+=fpType(hqTypeFor(era))*(ech-1);r={v:Math.round(v),src:[t.n],est:1};}}
